 table=mdtable(['Cell','threshold','healthy events/512','simultaneous upper95','pass'],[[r['cell'],f"{r['threshold']:.6g}",r['healthy_calibrated']['events'],f"{r['simultaneous_one_sided_upper']:.4f}",r['simultaneous_one_sided_upper']<=.1] for r in prim]);write('HEALTHY_CALIBRATION_TABLE.md',table)
